import type { NextConfig } from "next";

/**
 * Precision Signal — static export for GitHub Pages.
 *
 * output: "export" keeps the core site fully pre-rendered, so every route
 * works without JavaScript and without a server (§73 Progressive Enhancement).
 * The image optimizer is disabled because GitHub Pages serves a static tree;
 * responsive AVIF/WebP/JPEG variants are pre-generated by
 * `scripts/optimize-media.mjs` and served through explicit srcset.
 */
const basePath = "/uriah-d-villa";

const nextConfig: NextConfig = {
  output: "export",
  basePath,
  trailingSlash: true,
  env: {
    // Raw <img> tags and any non-Link navigation do not get basePath
    // applied automatically, so it is exposed here rather than duplicated
    // across components.
    NEXT_PUBLIC_BASE_PATH: basePath,
  },
  images: {
    unoptimized: true,
  },
  reactStrictMode: true,
};

export default nextConfig;
